import{_ as e,o as r,c as a,a as d}from"./chunks/framework.Ld7uezS_.js";const b=JSON.parse('{"title":"权威依据与版本边界","description":"","frontmatter":{},"headers":[],"relativePath":"sources.md","filePath":"sources.md","lastUpdated":1787292351000}'),l={name:"sources.md"};function n(o,t,i,s,h,c){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="权威依据与版本边界" tabindex="-1">权威依据与版本边界 <a class="header-anchor" href="#权威依据与版本边界" aria-label="Permalink to &quot;权威依据与版本边界&quot;">​</a></h1><blockquote><p>本页是本站的来源单一入口。页面中的固定结论，优先引用国家职业技能标准、消防职业技能鉴定考试网和现行国家标准；地方公告只用于说明当地考务安排，不外推为全国统一规则。</p><p><strong>核查日期：2026-08-21。</strong> 本轮继续对 GB 50166-2019、GB 50261-2017、GB 50974-2014、GB 50444-2008 及官方鉴定公告入口进行了公开目录或官方页面交叉核对。国家标准、法律法规和鉴定公告可能更新，报考前仍应打开原链接复核。</p></blockquote><h2 id="_1-职业标准与鉴定口径" tabindex="-1">1. 职业标准与鉴定口径 <a class="header-anchor" href="#_1-职业标准与鉴定口径" aria-label="Permalink to &quot;1. 职业标准与鉴定口径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>来源</th><th>版本/日期</th><th>本站采用范围</th><th>链接</th></tr></thead><tbody><tr><td>《消防设施操作员国家职业技能标准（2019年版）》</td><td>人社厅发〔2019〕63号；自2020-01-01施行</td><td>职业定义、等级、两个职业方向、职业功能、理论与技能鉴定方式、60分合格基线、关键技能</td><td><a href="https://xfhyjd.119.gov.cn/zwossread/open1File/FirefightingSkillsAssessmentSystem/2025-11-13/4f0f6d863cf843228b5ce52030b59bb7/16193156145476990d82b-cb9d-43a7-a5f0-522abe3d1f8c%E5%9B%BD%E5%AE%B6%E8%81%8C%E4%B8%9A%E6%8A%80%E8%83%BD%E6%A0%87%E5%87%86%E2%80%94%E2%80%94%E6%B6%88%E9%98%B2%E8%AE%BE%E6%96%BD%E6%93%8D%E4%BD%9C%E5%91%98.pdf" target="_blank" rel="noreferrer">消防职业技能鉴定考试网 PDF</a></td></tr><tr><td>人社部、应急管理部办公厅《关于颁布消防设施操作员国家职业技能标准的通知》</td><td>人社厅发〔2019〕63号；2019-05-10</td><td>标准发布依据</td><td><a href="https://www.cccf.net.cn/article/5994" target="_blank" rel="noreferrer">中国消防产品信息网转载页</a></td></tr><tr><td>消防职业技能鉴定考试网</td><td>持续更新</td><td>报名入口、考试公告、考务安排、考生须知和成绩/证书信息</td><td><a href="https://xfhyjd.119.gov.cn/" target="_blank" rel="noreferrer">官网</a></td></tr><tr><td>《消防设施操作员国家职业标准（2026年版）》</td><td>2026-10-01起施行（公开信息）</td><td>作为即将生效的新版本参考；施行前不替代2019年版当前学习基线</td><td><a href="https://xfhyjd.119.gov.cn/zwossread/open1File/IntegrationExaminationSystem/2026-05-10/66e700937fa14bd8aa1b18270ecc6136/%E5%9B%BD%E5%AE%B6%E8%81%8C%E4%B8%9A%E6%A0%87%E5%87%86%E3%80%8A%E6%B6%88%E9%98%B2%E8%AE%BE%E6%96%BD%E6%93%8D%E4%BD%9C%E5%91%98%EF%BC%882026%E5%B9%B4%E7%89%88%EF%BC%89%E3%80%8B.pdf" target="_blank" rel="noreferrer">消防职业技能鉴定考试网文件</a></td></tr><tr><td>《关于进一步规范消防设施操作员职业技能鉴定技能考核的公告》及各站落实公告</td><td>2024-11-19起，新报名考生技能考核一律采用现场实际操作；历史报名、补考和过渡安排需按适用公告区分</td><td>新报名考生技能考核方式、现场考核提醒；不外推地方过渡条款</td><td><a href="https://xfhyjd.119.gov.cn/#/detail/tzgg/2196" target="_blank" rel="noreferrer">考试网公告详情</a></td></tr><tr><td>四川省消防救援总队鉴定站《备考温馨提示》</td><td>2025年发布</td><td>“一个标准、一本大纲、一套教材”的备考路径；地方实践提示</td><td><a href="https://xfhyjd.119.gov.cn/#/detail/tzgg/2887" target="_blank" rel="noreferrer">公告</a></td></tr></tbody></table><h2 id="当前考试学习基线" tabindex="-1">当前考试学习基线 <a class="header-anchor" href="#当前考试学习基线" aria-label="Permalink to &quot;当前考试学习基线&quot;">​</a></h2><blockquote><p><strong>版本过渡提示（2026-08-21）</strong>：消防职业技能鉴定考试网已公开《消防设施操作员国家职业标准（2026年版）》相关文件，公开信息显示自 2026-10-01 起施行。当前日期尚未到施行日，本页对本站现有课程仍以 2019 年版作为当前学习基线；在 2026-10-01 之后，必须重新核对职业方向、职业功能、申报条件、技能要求和考核口径，不能继续把 2019 年版当作唯一依据。</p></blockquote><p>本站面向检测维修保养方向的学习，优先采用官方鉴定站提示的三类备考材料：</p><ol><li><strong>一个标准</strong>：《国家职业技能标准—消防设施操作员（2019年版）》；</li><li><strong>一本大纲</strong>：《消防设施操作员职业技能鉴定考核大纲（试行）》；</li><li><strong>一套教材</strong>：官方《消防设施操作员国家职业资格培训教材》对应版本。</li></ol><p>法律法规、强制性工程建设规范、国家标准、设备说明书和当地当批次评分要求，分别用于核验具体条款、系统参数、设备操作和现场判定。培训机构自编题库、旧“建（构）筑物消防员”教材和网络回忆题不能自动视为官方统一考试材料。</p><h3 id="检测维修保养方向标准映射" tabindex="-1">检测维修保养方向标准映射 <a class="header-anchor" href="#检测维修保养方向标准映射" aria-label="Permalink to &quot;检测维修保养方向标准映射&quot;">​</a></h3><p>2019版标准的本方向核心职业功能为：</p><table tabindex="0"><thead><tr><th>编号</th><th>职业功能</th><th>课程主线</th></tr></thead><tbody><tr><td>2</td><td>操作消防设施</td><td>2.1 火灾自动报警系统；2.2 自动灭火系统；2.3 其他消防设施</td></tr><tr><td>3</td><td>保养消防设施</td><td>3.1 火灾自动报警系统；3.2 自动灭火系统；3.3 其他消防设施</td></tr><tr><td>4</td><td>维修消防设施</td><td>4.1 火灾自动报警系统；4.2 自动灭火系统；4.3 其他消防设施</td></tr><tr><td>5</td><td>检测消防设施</td><td>5.1 火灾自动报警系统；5.2 自动灭火系统；5.3 其他消防设施</td></tr></tbody></table><blockquote><p>具体技能项目、知识要求和关键技能标记必须回到标准 PDF 与考核大纲原文核对；本站不把转录摘要或地方培训资料当作唯一证据。</p></blockquote><h2 id="_2-国家法律法规与工程建设标准" tabindex="-1">2. 国家法律法规与工程建设标准 <a class="header-anchor" href="#_2-国家法律法规与工程建设标准" aria-label="Permalink to &quot;2. 国家法律法规与工程建设标准&quot;">​</a></h2><p>下列文件只在本站涉及相应主题时引用。标准的具体条文、版本和是否被替代，应以国家标准全文公开系统或主管部门发布文本为准。</p><ul><li><a href="https://flk.npc.gov.cn/" target="_blank" rel="noreferrer">全国人大国家法律法规数据库</a>：检索《中华人民共和国消防法》《中华人民共和国安全生产法》等现行法律文本；页面中的法律条文引用以该数据库最新文本为准。</li><li><a href="https://www.gov.cn/xinwen/2021-06/11/content_5616916.htm" target="_blank" rel="noreferrer">《全国人民代表大会常务委员会关于修改〈中华人民共和国安全生产法〉的决定》</a>：2021-06-10 通过并公布，供核对安全生产法修订信息。</li><li>《中华人民共和国消防法》：消防工作方针、单位消防安全职责和法律责任。<strong>注意：部分全国人大旧页面仍保留修法前“公安机关消防机构”等机构称谓，不作为现行机构称谓的唯一依据。</strong></li><li>《中华人民共和国安全生产法》：安全生产主体责任、从业人员权利义务和作业安全。</li><li><a href="https://openstd.samr.gov.cn/" target="_blank" rel="noreferrer">国家标准全文公开系统</a>：查询 GB/T、GB、GB 55036 等标准的现行状态、发布日期和全文信息。</li><li><a href="https://wglj.gz.gov.cn/attachment/7/7296/7296992/8986976.pdf" target="_blank" rel="noreferrer">GB 55036-2022《消防设施通用规范》官方公开文本</a>：2022-07-15 发布，2023-03-01 实施；全文为强制性工程建设规范，现行工程建设标准与其不一致时以其规定为准。</li><li><a href="https://www.gov.cn/zhengce/zhengceku/2023-01/30/content_5739161.htm" target="_blank" rel="noreferrer">GB 55037-2022《建筑防火通用规范》发布公告</a>：2022-12-27 公告，2023-06-01 实施；全文为强制性工程建设规范，公告明确与现行工程建设标准不一致时以其规定为准。</li><li>学习时不得以本站摘要替代完整条文；GB 50016、GB 50116、GB 50084 等标准的相关强制性条文可能已由通用规范调整或替代，具体以国家标准全文公开系统和发布公告为准。</li><li>GB 50116《火灾自动报警系统设计规范》：火灾自动报警系统设计；具体版本和与通用规范的适用关系需回到国家标准全文公开系统核对。</li><li><a href="https://www.ndls.org.cn/standard/detail/2ac28ec76ebffdb2275732bcb9063e21" target="_blank" rel="noreferrer">GB 50166-2019《火灾自动报警系统施工及验收标准》公开目录</a>：适用于建（构）筑物火灾自动报警系统的施工、检测、验收及维护保养；公开目录显示发布日期 2019-11-22、实施日期 2020-03-01。本标准替代 GB 50166-2007；不适用于火药、炸药、弹药、火工品生产和储存场所。具体条文仍以标准全文为准。</li><li>GB 50084《自动喷水灭火系统设计规范》：自动喷水灭火系统设计；具体版本和与通用规范的适用关系需回到国家标准全文公开系统核对。</li><li><a href="https://ndls.org.cn/standard/detail/af2c361d544ecd02da7be14d268c1946" target="_blank" rel="noreferrer">GB 50261-2017《自动喷水灭火系统施工及验收规范》公开目录</a>：公开目录标注现行，发布日期 2017-05-27、实施日期 2018-01-01；适用于工业与民用建筑自动喷水灭火系统的施工、验收及维护管理。涉及 GB 55036-2022 的部分代替关系时，需按具体条文复核。</li><li><a href="https://ndls.cnis.ac.cn/standard/detail/f206a7a67c68102d90a31f9515f75af3" target="_blank" rel="noreferrer">GB 50974-2014《消防给水及消火栓系统技术规范》公开目录</a>：公开目录标注现行，发布日期 2014-01-29、实施日期 2014-10-01；适用于新建、扩建、改建工业、民用、市政等建设工程的消防给水及消火栓系统设计、施工和维护管理。与 GB 55036-2022 的部分代替关系需按条文复核。</li><li><a href="https://www.ndls.org.cn/standard/detail/6bd218d4a9e47082dce3bb8204b5f5f3" target="_blank" rel="noreferrer">GB 51251-2017《建筑防烟排烟系统技术标准》公开目录</a>：防烟排烟系统的设计、施工、验收及维护管理；公开目录标注现行，发布日期 2017-11-20，实施日期 2018-08-01。本页不替代标准全文。</li><li><a href="https://www.ndls.org.cn/standard/detail/b2283d7e92d4a88629c733ec0a025e99" target="_blank" rel="noreferrer">GB 51309-2018《消防应急照明和疏散指示系统技术标准》公开目录</a>：应急照明和疏散指示系统的设计、施工、调试、检测、验收与维护保养；公开目录标注现行，发布日期 2018-07-10，实施日期 2019-03-01。涉及 GB 55036-2022 的适用关系时，需按具体条文和工程阶段复核。</li><li><a href="https://www.ndls.org.cn/standard/detail/6d43f102ba0d10a9e8a8da378551955e" target="_blank" rel="noreferrer">GB 50444-2008《建筑灭火器配置验收及检查规范》公开目录</a>：公开目录标注现行，发布日期 2008-08-13、实施日期 2008-11-01；适用于工业与民用建筑灭火器的安装设置、验收、检查和维护，不适用于炸药、弹药、火工品、花炮生产或储存场所。与 GB 55036-2022 的部分代替关系及强制性条文适用性需按现行条文复核。</li><li><a href="https://std.samr.gov.cn/gb/search/gbDetailed?id=71F772D7D6ACD3A7E05397BE0A0AB82A" target="_blank" rel="noreferrer">GB 25201-2010《建筑消防设施的维护管理》国家标准详情</a>：建筑消防设施日常维护管理；公开目录标注现行，发布日期 2010-09-26，实施日期 2011-03-01，上次复审日期 2022-01-13，修订计划状态需持续关注。</li></ul><h2 id="_3-使用说明" tabindex="-1">3. 使用说明 <a class="header-anchor" href="#_3-使用说明" aria-label="Permalink to &quot;3. 使用说明&quot;">​</a></h2><ol><li><strong>国家职业标准 ≠ 当批次考试评分表</strong>：本站用职业标准组织学习范围；具体题量、考试时长、技能项目分值、现场路线和关键技能门槛，以报考地鉴定站当批次公告、准考证和现场评分表为准。</li><li><strong>教材 ≠ 现行标准全文</strong>：培训教材用于建立知识体系，遇到固定数值、标准名称或操作要求，优先回查现行标准和设备说明书。</li><li><strong>无法确认就不写死</strong>：本站对检测阈值、动作时间、允许误差等易随设备/标准变化的内容，不给出脱离依据的统一数字。</li><li><strong>实操必须在安全条件下训练</strong>：涉及消防泵、风机、卷帘、气体灭火、电气部件和联动设备时，只能在鉴定站或有资质人员指导下进行，不把网页步骤当作现场授权。</li></ol>',18)])])}const g=e(l,[["render",n]]);export{b as __pageData,g as default};
